import stationData from "@/data/stations.json";
import {
  editDistance,
  haversineKm,
  resolvePlace,
  type ResolvedPlace,
} from "./places";

export type FuelInfo = { available: boolean; price: number | null };

// Fields marked optional/nullable may be missing from Redan's station list
// (src/data/stations.json is generated by scripts/import_stations.py).
export type Station = {
  id: string;
  name: string;
  aliases?: string[];
  city: string;
  address?: string | null;
  /** The site's cell number — always the contact to give customers. */
  phone?: string | null;
  /** Only set when the site has no cell number. */
  landline?: string | null;
  manager?: string | null;
  lat: number | null;
  lng: number | null;
  /**
   * True when lat/lng is the centre of the station's suburb or town (from the
   * place gazetteer) rather than the site itself, because the spreadsheet has
   * no coordinates for it yet.
   */
  locationApprox?: boolean;
  /** For approximate locations: placed at its suburb, or only at its town centre. */
  locationLevel?: "suburb" | "town";
  mapsLink?: string | null;
  /** Send map/directions links to the address, not the coordinates. */
  routeByAddress?: boolean;
  hours: "24h" | "12h";
  openFrom?: string | null;
  openTo?: string | null;
  fuel: { blend: FuelInfo; diesel: FuelInfo };
  lubricants: boolean;
  refreshments?: boolean;
  lpg?: boolean;
  /** USD per kg, when the station list gives one. */
  lpgPrice?: number | null;
};

export type RankedStation = Station & { distanceKm: number };

/**
 * Where to look a station up in the place gazetteer when its own name is not
 * a place there, or names the wrong one. Anything not listed is looked up as
 * "<station name>, <town>", falling back to the town.
 */
const LOCATION_HINTS: Record<string, string> = {
  "Redan Zindoga": "Waterfalls, Harare",
  "Redan Mandava": "Zvishavane",
  "Redan Ngundu": "Ngundu Halt",
  "Redan Nyamahobogo": "Rushinga",
  // "Seke" alone is the rural district south of Chitungwiza.
  "Redan Seke Road": "Harare",
};

const POPULATED = ["city", "suburb", "town", "village", "business centre"];

/**
 * Stations without coordinates in the spreadsheet get the centre of their
 * suburb (if the gazetteer knows it and it lies in the station's town) or of
 * their town, so they can still be ranked by distance. No fuzzy matching here:
 * a near-miss spelling could put a station in the wrong province.
 */
type ApproxLocation = { lat: number; lng: number; level: "suburb" | "town" };

function approxLocation(s: Station): ApproxLocation | null {
  const town = resolvePlace(s.city, { fuzzy: false });
  const hint = LOCATION_HINTS[s.name];
  if (hint) {
    const at = resolvePlace(hint, { fuzzy: false });
    if (!at) return null;
    const level = town && at.name === town.name ? "town" : "suburb";
    return { lat: at.lat, lng: at.lng, level };
  }

  for (const label of [s.name, ...(s.aliases ?? [])]) {
    const site = resolvePlace(`${label.replace(/^Redan\s+/i, "")}, ${s.city}`, { fuzzy: false });
    if (
      site &&
      site.name !== town?.name &&
      POPULATED.includes(site.kind) &&
      (!town || haversineKm(site.lat, site.lng, town.lat, town.lng) <= 60)
    ) {
      return { lat: site.lat, lng: site.lng, level: "suburb" };
    }
  }
  return town ? { lat: town.lat, lng: town.lng, level: "town" } : null;
}

const stations: Station[] = (stationData.stations as Station[]).map((s) => {
  if (s.lat !== null && s.lng !== null) return s;
  const at = approxLocation(s);
  return at
    ? { ...s, lat: at.lat, lng: at.lng, locationApprox: true, locationLevel: at.level }
    : s;
});

// Towns with several stations (Harare, Bulawayo, ...). A station placed only
// at the centre of one of these could be anywhere in it; a town's only
// station sitting at the town centre is a fair approximation.
const stationsPerTown = new Map<string, number>();
for (const s of stations) {
  const town = s.city.trim().toLowerCase();
  stationsPerTown.set(town, (stationsPerTown.get(town) ?? 0) + 1);
}

/**
 * Rough radius of a town, from its population: a customer this close to the
 * centre is "in town", where a town-centre distance means nothing. Farther
 * out (Zimunya, 15 km from Mutare) the approximate distance is useful.
 */
const townRadius = new Map<string, number>();
function radiusKm(city: string): number {
  const key = city.trim().toLowerCase();
  if (!townRadius.has(key)) {
    const pop = resolvePlace(city, { fuzzy: false })?.population ?? 0;
    townRadius.set(key, pop > 1_000_000 ? 12 : pop > 500_000 ? 10 : 6);
  }
  return townRadius.get(key)!;
}

/** True when this station's distance means nothing to a customer in its town. */
function distanceUnknownInTown(s: RankedStation): boolean {
  return (
    s.locationLevel === "town" &&
    s.distanceKm >= 0 &&
    s.distanceKm < radiusKm(s.city) &&
    (stationsPerTown.get(s.city.trim().toLowerCase()) ?? 0) > 1
  );
}

/** True when the seed file is still placeholder data rather than Redan's list. */
export const STATION_DATA_IS_PLACEHOLDER =
  stationData._meta?.status === "PLACEHOLDER";


/** False until map locations have been added for the stations. */
export const STATIONS_HAVE_LOCATIONS = stations.some(
  (s) => typeof s.lat === "number" && typeof s.lng === "number",
);

export type StationQuery = {
  lat?: number;
  lng?: number;
  city?: string;
  fuelType?: "blend" | "diesel" | "any";
  onlyOpen24h?: boolean;
};

export type StationSearch = {
  stations: RankedStation[];
  /** The Zimbabwean place the customer named, when it was found in the gazetteer. */
  place?: ResolvedPlace;
  /**
   * True when Redan has no station in the place the customer named, so the
   * stations are simply the nearest ones to it.
   */
  nearestOnly: boolean;
};

const cleanName = (t: string) =>
  t
    .toLowerCase()
    .replace(/\b(redan|service|station|site|garage)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
const byName = (s: Station) => [s.name, ...(s.aliases ?? [])];
const byAny = (s: Station) => [s.city, s.address ?? "", ...byName(s)];
const splitParts = (place: string) =>
  place.split(/,|\bin\b/i).map(cleanName).filter(Boolean);

function matching(pool: Station[], needle: string, fields: (s: Station) => string[]) {
  return needle
    ? pool.filter((s) => fields(s).some((f) => f.toLowerCase().includes(needle)))
    : [];
}

/**
 * Stations whose own name is in the query. Models often pass things like
 * "Redan Skyway, Harare" or "Skyway station", so filler words are dropped and
 * each comma/"in"-separated part is tried, so "Skyway, Harare" means Skyway,
 * not all of Harare. Single whole words count too ("Zindoga Waterfalls").
 */
/** Words in station names too generic to identify a station on their own. */
const GENERIC_NAME_WORDS = new Set([
  "park", "road", "street", "mall", "city", "centre", "center", "main",
  "first", "second", "hill", "hills", "view", "north", "south", "east", "west",
  "truck", "stop", "highway", "megawatt",
]);

function matchStationName(pool: Station[], place: string): Station[] {
  const whole = cleanName(place);
  const direct = matching(pool, whole, byName);
  if (direct.length > 0) return direct;
  for (const part of splitParts(place)) {
    const hit = matching(pool, part, byName);
    if (hit.length > 0) return hit;
  }
  // A whole phrase that is itself a place ("Msasa Park", a Harare suburb) is
  // ranked by distance from that place, not matched word by word.
  if (resolvePlace(place, { fuzzy: false })?.name.toLowerCase() === whole) return [];
  const words = whole
    .split(/[^a-z0-9]+/)
    .filter((w) => w.length >= 4 && !GENERIC_NAME_WORDS.has(w));
  return pool.filter((s) =>
    byName(s).some((f) =>
      cleanName(f)
        .split(/[^a-z0-9]+/)
        .some((t) => words.includes(t)),
    ),
  );
}

/** Stations in a town (or at an address) named in the query. */
function matchTown(pool: Station[], place: string): Station[] {
  const direct = matching(pool, cleanName(place), byAny);
  if (direct.length > 0) return direct;
  for (const part of splitParts(place)) {
    const hit = matching(pool, part, byAny);
    if (hit.length > 0) return hit;
  }
  return [];
}

/** A one- or two-letter typo in a station or town name ("Zindonga"). */
function matchTypo(pool: Station[], place: string): Station[] {
  const words = cleanName(place).split(" ").filter((w) => w.length >= 4);
  const close = (w: string, target: string) =>
    Math.abs(w.length - target.length) <= 2 &&
    editDistance(w, target) <= (w.length >= 7 ? 2 : 1);
  for (const fields of [byName, byAny]) {
    const hit = pool.filter((s) =>
      fields(s).some((f) =>
        f.toLowerCase().split(/\s+/).some((t) => words.some((w) => close(w, t))),
      ),
    );
    if (hit.length > 0) return hit;
  }
  return [];
}

/**
 * Station names mentioned anywhere in a free-text customer message, e.g.
 * "Ndoda kuziva nezve Redan Zindoga" -> ["Zindoga"]. Matches station names and
 * aliases only (not towns, which would pull in every Harare site), allowing a
 * one-letter typo in single-word names of five letters or more.
 */
export function stationsMentionedIn(text: string): string[] {
  const plain = text.toLowerCase().replace(/[^a-z0-9\s]/g, " ");
  // Shona and isiNdebele attach place prefixes to names: "kuZindoga",
  // "kwaMbare", "paSkyway", "eLobengula". Match with and without them.
  const unprefixed = plain.replace(/\b(kwa|ku|ko|pa|e)(?=[a-z]{4,})/g, "");
  const lower = ` ${plain} ${unprefixed} `;
  const words = lower.split(/\s+/).filter((w) => w.length >= 5);
  const found = new Set<string>();
  for (const s of stations) {
    for (const label of [s.name, ...(s.aliases ?? [])]) {
      const key = label.toLowerCase().replace(/^redan\s+/, "").trim();
      const exact = lower.includes(` ${key} `);
      const typo =
        !key.includes(" ") &&
        key.length >= 5 &&
        words.some((w) => Math.abs(w.length - key.length) <= 1 && editDistance(w, key) <= 1);
      if (exact || typo) found.add(s.name.replace(/^Redan\s+/, ""));
    }
  }
  return [...found];
}

/**
 * Returns every matching station, ranked by distance from the customer's
 * coordinates or from the place they named. Filters are applied before
 * ranking so "nearest 3 with diesel" returns three stations that actually
 * have diesel. The caller decides how many to show.
 *
 * A place name is tried, in order, as: a station's name; a town with Redan
 * stations (ranked from the suburb, if one was named too: "Highfield,
 * Harare"); any other place in Zimbabwe, giving the nearest stations to it;
 * a misspelt station or town; a misspelt place.
 */
export function findStations(q: StationQuery): StationSearch {
  const fuelType = q.fuelType ?? "any";

  let pool = stations;

  if (fuelType !== "any") {
    pool = pool.filter((s) => s.fuel[fuelType].available);
  }
  if (q.onlyOpen24h) {
    pool = pool.filter((s) => s.hours === "24h");
  }
  const hasCoords = typeof q.lat === "number" && typeof q.lng === "number";
  let origin = hasCoords ? { lat: q.lat!, lng: q.lng! } : null;
  let place: ResolvedPlace | undefined;
  let nearestOnly = false;
  const located = (list: Station[]) => list.filter((s) => s.lat !== null && s.lng !== null);

  if (q.city) {
    const named = matchStationName(pool, q.city);
    const town = named.length > 0 ? [] : matchTown(pool, q.city);
    place =
      named.length > 0 ? undefined : (resolvePlace(q.city, { fuzzy: false }) ?? undefined);

    if (named.length > 0) {
      pool = named;
    } else if (town.length > 0) {
      pool = town;
    } else if (place) {
      pool = located(pool);
      nearestOnly = true;
    } else {
      const typo = matchTypo(pool, q.city);
      place = typo.length > 0 ? undefined : (resolvePlace(q.city) ?? undefined);
      if (typo.length > 0) {
        pool = typo;
      } else if (place) {
        pool = located(pool);
        nearestOnly = true;
      } else if (!hasCoords) {
        // Not a station, town or any place we know, and no coordinates to
        // fall back on. Return nothing rather than unrelated stations —
        // handing the model arbitrary stations here is how a bot ends up
        // quoting a Harare price for a town it does not serve.
        return { stations: [], nearestOnly: false };
      }
      // With coordinates we can still rank the full pool by real distance, so
      // an unrecognised place name is not fatal.
    }
    if (!origin && place) origin = place;
  } else if (hasCoords) {
    // Only stations with a known location can be ranked by distance.
    pool = located(pool);
  }

  const ranked: RankedStation[] = pool.map((s) => ({
    ...s,
    distanceKm:
      origin && s.lat !== null && s.lng !== null
        ? Number(haversineKm(origin.lat, origin.lng, s.lat, s.lng).toFixed(1))
        : -1,
  }));

  if (origin) {
    // Stations without a location (-1) go last. A station placed only at its
    // town centre has no real distance for a customer inside that town: it
    // ranks as if at the town's edge, after stations known to be closer but
    // ahead of anything farther away (Mkoba -> the Gweru stations, not Kwekwe).
    const effective = (x: RankedStation) =>
      x.distanceKm < 0 ? Infinity : distanceUnknownInTown(x) ? radiusKm(x.city) : x.distanceKm;
    ranked.sort((a, b) => effective(a) - effective(b) || a.distanceKm - b.distanceKm);
  }

  return { stations: ranked, place, nearestOnly };
}


function fuelLine(f: FuelInfo, label = ""): string {
  if (!f.available) return "not available";
  return f.price !== null
    ? `${label}$${f.price.toFixed(2)}/L`
    : `${label}available (pump price not listed — give ZERA's published price from the knowledge base with its date, and say to confirm at the station)`;
}

function lpgLine(s: Station): string {
  if (!s.lpg) return "no";
  return typeof s.lpgPrice === "number"
    ? `yes, $${s.lpgPrice.toFixed(2)}/kg`
    : "yes (LPG price not listed — tell the customer to confirm it at the station)";
}

function hoursLine(s: Station): string {
  if (s.hours === "24h") return "24 hours, every day";
  return s.openFrom && s.openTo
    ? `12 hours (${s.openFrom}–${s.openTo}), every day`
    : "NOT open 24 hours: a 12-hour station. Exact opening and closing times are not supplied, so tell the customer to call the station to confirm.";
}

/**
 * Where a map or directions link for this station should point: its exact
 * coordinates when trusted, otherwise its name and address (or town) for
 * Google Maps to find.
 */
export function stationRouteTarget(s: Station): string {
  const exact = s.lat !== null && s.lng !== null && !s.locationApprox;
  if (exact && !(s.routeByAddress && s.address)) return `${s.lat},${s.lng}`;
  return s.address ? `${s.name}, ${s.address}, Zimbabwe` : `${s.name}, ${s.city}, Zimbabwe`;
}

/** A compact, model-friendly rendering of a station result. */
export function formatStation(s: RankedStation): Record<string, unknown> {
  // An approximate location is only the suburb or town centre, so the map
  // link searches for the station by name instead of pinning that point.
  const hasLocation = s.lat !== null && s.lng !== null && !s.locationApprox;
  // Pin links to the coordinates only when they are exact and trusted for routing.
  const pinByCoords = hasLocation && !(s.routeByAddress && s.address);
  return {
    name: s.name,
    town: s.city,
    // Missing fields are left out so the model doesn't list "not listed" lines.
    ...(s.address
      ? { address: s.address }
      : { location: `No street address on file — give the town (${s.city}) and the map link.` }),
    phone: s.phone
      ? `${s.phone} (site cell number)`
      : s.landline
        ? `${s.landline} (landline — this site has no cell number)`
        : "not listed",
    ...(s.manager && { site_manager: s.manager }),
    // Ready to quote: "about 7 km away". Only present when a distance is known.
    ...(s.distanceKm >= 0 && {
      // A station placed only at its town centre has no meaningful distance
      // for a customer inside that town; from farther away it is fine.
      distance: distanceUnknownInTown(s)
        ? `somewhere in ${s.city} — exact distance not known (say "in ${s.city}" instead of a distance)`
        : s.locationApprox
        ? `about ${Math.max(1, Math.round(s.distanceKm))} km away (straight line, approximate: measured to the centre of the station's suburb or town)`
        : `about ${s.distanceKm < 10 ? s.distanceKm.toFixed(1) : Math.round(s.distanceKm)} km away (straight line)`,
    }),
    // Seed data's hours are made up, so only real station lists report them.
    ...(STATION_DATA_IS_PLACEHOLDER ? {} : { operating_hours: hoursLine(s) }),
    blend: fuelLine(s.fuel.blend, "Petrol Blend: "),
    diesel: fuelLine(s.fuel.diesel, "Diesel 50: "),
    lubricants: s.lubricants ? "yes" : "no",
    ...(s.refreshments !== undefined && { refreshments: s.refreshments ? "yes" : "no" }),
    ...(s.lpg !== undefined && { lpg_gas: lpgLine(s) }),
    maps_link: pinByCoords
      ? `https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lng}`
      : (s.mapsLink ??
        `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
          s.address ? `${s.name}, ${s.address}, Zimbabwe` : `${s.name} ${s.city} Zimbabwe`,
        )}`),
    // Turn-by-turn directions. With no origin, Google Maps starts from the
    // customer's current location on their phone.
    directions_link: `https://www.google.com/maps/dir/?api=1&travelmode=driving&destination=${encodeURIComponent(stationRouteTarget(s))}`,
  };
}
